import math
from functools import reduce

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def lcm_list(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

# Parameters
Ns = [1, 2, 3, 4]
Ks = [1, 2, 3]

results = {}

for n in Ns:
    results[n] = {}
    for k in Ks:
        # Calculate x_k
        start_k = k
        end_k = k + n - 1
        x_k = lcm_list(range(start_k, end_k + 1))

        # Calculate x_{k+1}
        start_k_plus_1 = k + 1
        end_k_plus_1 = k + 1 + n - 1
        x_k_plus_1 = lcm_list(range(start_k_plus_1, end_k_plus_1 + 1))

        # Determine comparison
        comparison = "x_{k+1} > x_k" if x_k_plus_1 > x_k else "x_{k+1} <= x_k"

        results[n][k] = {
            "x_k": x_k,
            "x_k_plus_1": x_k_plus_1,
            "comparison": comparison
        }

# Print results in a structured way
print("--- Calculation Results ---")
for n, k_data in results.items():
    print(f"\nN = {n}:")
    for k, data in k_data.items():
        print(f"  k = {k}:")
        print(f"    x_k = {data['x_k']}")
        print(f"    x_{k+1} = {data['x_k_plus_1']}")
        print(f"    Comparison: {data['comparison']}")

# Specific check for n=3
print("\n--- Specific Check for N=3 ---")
for k in Ks:
    data = results[3][k]
    if data['comparison'] == "x_{k+1} <= x_k":
        print(f"N=3, k={k} satisfies x_{k+1} <= x_k:")
        print(f"  x_k = {data['x_k']}")
        print(f"  x_{k+1} = {data['x_k_plus_1']}")

